package de.walahi.novosmp.clan;import de.walahi.novosmp.NovoSMPPlugin;import de.walahi.smpcore.commands.framework.BaseCommand;import org.bukkit.Bukkit;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;
public final class ClanPartyCommand extends BaseCommand{private final ClanManager clans;public ClanPartyCommand(NovoSMPPlugin p,ClanManager c){super(p);clans=c;}protected String permission(){return "smpcore.clan.use";}protected boolean execute(CommandSender s,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage("Nur für Spieler.");return true;}if(a.length==0){clans.reply(p,"/cp invite|accept|deny|leave|kick|info");return true;}String sub=a[0].toLowerCase();String result=switch(sub){case "invite"->{Player t=a.length>1?Bukkit.getPlayerExact(a[1]):null;yield t==null?"Spieler muss online sein.":clans.parties().invite(p,t);}case "accept"->clans.parties().accept(p);case "deny"->clans.parties().deny(p.getUniqueId());case "leave"->clans.parties().leave(p.getUniqueId());case "kick"->{Player t=a.length>1?Bukkit.getPlayerExact(a[1]):null;yield t==null?"Spieler muss online sein.":clans.parties().kick(p.getUniqueId(),t.getUniqueId());}case "info"->clans.parties().info(p.getUniqueId());default->"/cp invite|accept|deny|leave|kick|info";};clans.reply(p,result);return true;}}
